const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const laSerena = ee.Geometry.Point([-71.25, -29.9]);
    const dataset = 'UCSB-CHG/CHIRPS/DAILY';
    const band = 'precipitation';
    const scale = 5000; // CHIRPS has a ~5.5km resolution

    // Using a recent, complete year as the target for this analysis.
    const targetYear = 2023;
    const targetStartDate = ee.Date.fromYMD(targetYear, 1, 1);
    const targetEndDate = ee.Date.fromYMD(targetYear, 7, 8); // End date is exclusive

    const historicalStartYear = 1990;
    const historicalEndYear = 2020;

    // 2. Data Acquisition & Processing
    // Calculate total rainfall for the target year period
    const targetCollection = ee.ImageCollection(dataset)
        .filterDate(targetStartDate, targetEndDate)
        .select(band);

    const targetCollectionSize = targetCollection.size().getInfo();
    if (targetCollectionSize === 0) {
        console.log(`No CHIRPS images found for target period: ${targetYear}-01-01 to ${targetYear}-07-07.`);
        console.log('C1');
        return;
    }

    const targetTotalPrecip = targetCollection.sum();
    const targetRainfallDict = targetTotalPrecip.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: laSerena,
        scale: scale,
        maxPixels: 1e9
    });
    const targetRainfall = ee.Number(targetRainfallDict.get(band));

    // Calculate the long-term average rainfall for the same period
    const years = ee.List.sequence(historicalStartYear, historicalEndYear);

    const annualTotals = years.map(function(year) {
        const startDate = ee.Date.fromYMD(year, 1, 1);
        const endDate = ee.Date.fromYMD(year, 7, 8);
        const yearlyCollection = ee.ImageCollection(dataset)
            .filterDate(startDate, endDate)
            .select(band);

        // Check for empty collections within the historical period as a precaution
        const collectionSize = yearlyCollection.size();
        const total = ee.Image(yearlyCollection.sum());

        // Return null if no images, otherwise return the sum
        return ee.Algorithms.If(collectionSize.gt(0), total, null);
    });

    // Filter out any nulls that might have resulted from empty collections
    const validAnnualTotals = ee.ImageCollection.fromImages(annualTotals.removeAll([null]));

    const historicalCollectionSize = validAnnualTotals.size().getInfo();
    if (historicalCollectionSize === 0) {
        console.log(`No CHIRPS images found for historical period: ${historicalStartYear}-${historicalEndYear}.`);
        console.log('C1');
        return;
    }

    const historicalMean = validAnnualTotals.mean();
    const historicalRainfallDict = historicalMean.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: laSerena,
        scale: scale,
        maxPixels: 1e9
    });
    const historicalRainfall = ee.Number(historicalRainfallDict.get(band));

    // 3. Validation & Final Answer
    const targetRainfallVal = targetRainfall.getInfo();
    const historicalRainfallVal = historicalRainfall.getInfo();

    if (targetRainfallVal === null || historicalRainfallVal === null) {
        console.log('Calculation failed: could not retrieve a valid rainfall value.');
        console.log(`Target Rainfall: ${targetRainfallVal}`);
        console.log(`Historical Average Rainfall: ${historicalRainfallVal}`);
        console.log('C3');
        return;
    }

    // Check pixel count for target year as C2 check. Only one point needed.
    const pixelCountDict = targetTotalPrecip.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: laSerena,
        scale: scale,
        maxPixels: 1e9
    });
    const pixelCount = ee.Number(pixelCountDict.get(band)).getInfo();

    if (pixelCount === 0) {
        console.log("No valid pixels found at the location for the target year.");
        console.log('C2');
        return;
    }

    console.log(`Location: La Serena, Chile (Point)`);
    console.log(`Period: January 1 to July 7`);
    console.log(`Target Year (2023) Rainfall: ${targetRainfallVal.toFixed(2)} mm`);
    console.log(`Historical Avg (1990-2020) Rainfall: ${historicalRainfallVal.toFixed(2)} mm`);
    console.log(`Comparison: Was ${targetYear} rainfall lower than the historical average?`);

    if (targetRainfallVal < historicalRainfallVal) {
        console.log('A');
    } else {
        console.log('B');
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('An error occurred during Earth Engine initialization or analysis.');
        console.error(e);
        console.log('D');
    }
}

initEE();
